#!/usr/bin/env node
/**
 * generate.mjs — tokens.json -> tokens.css, Tokens.kt, Tokens.swift
 *
 * Run it after ANY change to tokens.json. Never hand-edit a generated file;
 * tools/check_tokens.mjs regenerates and diffs, and fails if they disagree.
 *
 *   node tokens/generate.mjs            # write the three files
 *   node tokens/generate.mjs --check    # exit 1 if any file is stale
 *
 * The three platforms cannot drift, because there is only one set of numbers.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const T = JSON.parse(readFileSync(join(HERE, 'tokens.json'), 'utf8'));
const CHECK = process.argv.includes('--check');

/* ---------- OKLCH -> sRGB. The whole band ramp comes out of this. ---------- */
export function oklch(L, C, H) {
  const h = (H * Math.PI) / 180;
  const a = C * Math.cos(h), b = C * Math.sin(h);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.2914855480 * b) ** 3;
  const lin = [
     4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
  ];
  const to8 = v => {
    v = Math.min(1, Math.max(0, v));
    const g = v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
    return Math.round(g * 255);
  };
  return '#' + lin.map(v => to8(v).toString(16).padStart(2, '0')).join('');
}

/* ---------- the four derived scales ---------- */
export const typeScale = () => {
  const { base, ratio, steps, round } = T.type;
  return Array.from({ length: steps }, (_, n) =>
    Math.round((base * ratio ** n) / round) * round);
};
export const radii = () => {
  const { card, step } = T.radius;
  return { chip: card - step * 2, inner: card - step, card, sheet: card + step, pill: T.radius.pill };
};
export const bandColour = (role, theme, band) => {
  const { L, C } = T.colour.bandRole[role][theme];
  const c = band === T.colour.neutralBand ? C * T.colour.neutralFactor : C;
  return oklch(L, c, T.colour.bandHue[band]);
};

/* ---------- the spring sampler: parameters -> linear() ---------- */
export function springSamples(durationMs, zeta, n = 26) {
  const w = (2 * Math.PI) / (durationMs / 1000);
  const wd = w * Math.sqrt(Math.max(0, 1 - zeta * zeta));
  const out = [];
  for (let i = 0; i < n; i++) {
    const t = (i / (n - 1)) * (durationMs / 1000);
    let y;
    if (zeta < 1) {
      y = 1 - Math.exp(-zeta * w * t) * (Math.cos(wd * t) + (zeta * w / wd) * Math.sin(wd * t));
    } else {
      y = 1 - Math.exp(-w * t) * (1 + w * t);           // critically damped
    }
    out.push(y);
  }
  out.push(1);
  return out.map(v => v.toFixed(4)).join(', ');
}

/* tokens.json carries $comment keys for humans; never emit them. */
const real = o => Object.entries(o).filter(([k]) => !k.startsWith('$'));

const BANDS = Object.keys(T.colour.bandHue);
const ROLES = Object.keys(T.colour.bandRole);
const ld = (l, d) => `light-dark(${l}, ${d})`;

/* ========================================================================= */
/* CSS                                                                        */
/* ========================================================================= */
function css() {
  const ts = typeScale(), r = radii(), L = [];
  L.push(`/* GENERATED by tokens/generate.mjs from tokens/tokens.json — do not edit.`);
  L.push(`   v${T.version} · ${T.date}`);
  L.push(``);
  L.push(`   light-dark() carries COLOURS ONLY. Never an opacity, never a`);
  L.push(`   multi-part value: a top-level comma makes it a three-argument call`);
  L.push(`   and the whole declaration is silently dropped. Shadows below are`);
  L.push(`   plain values with a real dark override, for exactly that reason. */`);
  L.push(``, `:root {`, `  color-scheme: light dark;`, ``);

  L.push(`  /* --- type: base ${T.type.base}, ratio ${T.type.ratio}, ${T.type.steps} steps --- */`);
  ts.forEach((v, i) => L.push(`  --t${i}: ${v}px;   /* ${T.type.roles['t' + i]} */`));
  L.push(``);
  for (const [k, v] of real(T.type.families)) L.push(`  --font-${k}: ${v};`);
  L.push(``);

  L.push(`  /* --- space: ${T.space.grid}px grid --- */`);
  T.space.steps.forEach((v, i) => L.push(`  --s${i}: ${v}px;`));
  L.push(``);

  L.push(`  /* --- radius: card ${T.radius.card}, step ${T.radius.step} --- */`);
  for (const [k, v] of real(r)) L.push(`  --r-${k}: ${v}px;`);
  L.push(``);

  L.push(`  /* --- ground --- */`);
  for (const [k, v] of real(T.colour.ground)) {
    const name = k.replace(/[A-Z]/g, c => '-' + c.toLowerCase());
    L.push(`  --${name}: ${ld(v.light, v.dark)};`);
  }
  L.push(``);

  L.push(`  /* --- bands: generated from ${Object.keys(T.colour.bandHue).length} hues + ${ROLES.length} L/C pairs.`);
  L.push(`         NEAR-MISS is the same ramp at ${T.colour.neutralFactor}x chroma — its band IS the neutral. --- */`);
  for (const role of ROLES) {
    const suffix = role === 'colour' ? '' : '-' + role;
    for (const b of BANDS) {
      L.push(`  --${b}${suffix}: ${ld(bandColour(role, 'light', b), bandColour(role, 'dark', b))};`);
    }
  }
  L.push(``);
  L.push(`  /* The rose's empty track is --text at ${T.rose.emptyAlpha}. It may NEVER be a band`);
  L.push(`     colour: NEAR-MISS's band is the neutral, so a band-coloured track`);
  L.push(`     leaves lit and unlit identical but for opacity. */`);
  L.push(`  --rose-empty: ${ld(T.colour.ground.text.light, T.colour.ground.text.dark)};`);
  L.push(`  --rose-empty-alpha: ${T.rose.emptyAlpha};`);
  L.push(``);

  L.push(`  /* --- band thresholds. The scorer emits \`fit\` only and every client`);
  L.push(`         derives the band, so this table had five copies. Now it has one. --- */`);
  for (const [k, v] of real(T.band.threshold)) L.push(`  --threshold-${k}: ${v};`);
  L.push(``);

  L.push(`  /* --- motion: real spring step responses, sampled --- */`);
  for (const [k, s] of real(T.motion.springs)) {
    L.push(`  --t-${k}: ${s.durationMs}ms;`);
    L.push(`  --spring-${k}: ${s.bezier ? `cubic-bezier(${s.bezier.join(', ')})`
                                        : `linear(${springSamples(s.durationMs, s.zeta)})`};`);
  }
  L.push(``);
  for (const [k, v] of real(T.motion.stagger)) L.push(`  --stagger-${k}: ${v}ms;`);
  for (const [k, v] of real(T.motion.travel))  L.push(`  --travel-${k}: ${v}px;`);
  for (const [k, v] of real(T.motion.pressScale)) L.push(`  --press-${k}: ${v};`);
  L.push(`  --t-breathe: ${T.motion.idle.breatheMs}ms;`);
  L.push(`  --breathe-floor: ${T.motion.idle.breatheFloor};`);
  L.push(`  --t-seek: ${T.motion.idle.seekMs}ms;`);
  L.push(``);

  L.push(`  /* --- elevation. Light: --surface is #ffffff, the ceiling, so hover`);
  L.push(`         cannot lift and carries in shadow alone. Dark: no shadow, so it`);
  L.push(`         carries entirely in lift. The asymmetry is the rule. --- */`);
  L.push(`  --sh-rest:  0 1px 2px rgba(75,68,57,.05), 0 6px 14px rgba(75,68,57,.06);`);
  L.push(`  --sh-hover: 0 2px 4px rgba(75,68,57,.06), 0 14px 30px rgba(75,68,57,.10);`);
  L.push(`  --sh-press: 0 1px 2px rgba(75,68,57,.08);`);
  L.push(`  --sh-sheet: 0 -2px 8px rgba(75,68,57,.06), 0 -18px 48px rgba(75,68,57,.16);`);
  L.push(`  --edge-rest:  ${ld('rgba(8,3,49,.08)', 'rgba(248,243,235,.13)')};`);
  L.push(`  --edge-hover: ${ld('rgba(8,3,49,.12)', 'rgba(248,243,235,.26)')};`);
  L.push(`  --hairline:   ${ld('rgba(8,3,49,.13)', 'rgba(248,243,235,.13)')};`);
  L.push(`  --surface-hover: ${ld('#ffffff', '#221a52')};`);
  L.push(`}`, ``);

  L.push(`/* Dark has no shadows: a warm shadow on ink reads as dirt. */`);
  L.push(`@media (prefers-color-scheme: dark) {`);
  L.push(`  :root:not([data-theme="light"]) { --sh-rest:none; --sh-hover:none; --sh-press:none; --sh-sheet:none; }`);
  L.push(`}`);
  L.push(`:root[data-theme="dark"]  { color-scheme: dark;  --sh-rest:none; --sh-hover:none; --sh-press:none; --sh-sheet:none; }`);
  L.push(`:root[data-theme="light"] { color-scheme: light; }`);
  L.push(``);
  L.push(`/* Market: the hero and the market chip ONLY. Colour law v2.3. */`);
  for (const [m, v] of real(T.colour.market)) {
    L.push(`html[data-market="${m}"] { --hero-a: ${v.hero[0]}; --hero-b: ${v.hero[1]}; }`);
  }
  return L.join('\n') + '\n';
}

/* ========================================================================= */
/* Kotlin / Compose.  stiffness = w^2, w = 2*pi/T.                            */
/* ========================================================================= */
function kotlin() {
  const ts = typeScale(), r = radii(), L = [];
  L.push(`// GENERATED by tokens/generate.mjs — do not edit. v${T.version}`);
  L.push(`package page.jobscout.design`, ``);
  L.push(`import androidx.compose.animation.core.*`);
  L.push(`import androidx.compose.ui.graphics.Color`);
  L.push(`import androidx.compose.ui.unit.dp`);
  L.push(`import androidx.compose.ui.unit.sp`, ``);
  L.push(`object Type {`);
  ts.forEach((v, i) => L.push(`    val t${i} = ${v}.sp   // ${T.type.roles['t' + i]}`));
  L.push(`}`, ``);
  L.push(`object Space {`);
  T.space.steps.forEach((v, i) => L.push(`    val s${i} = ${v}.dp`));
  L.push(`}`, ``);
  L.push(`object Radius {`);
  for (const [k, v] of real(r)) L.push(`    val ${k} = ${k === 'pill' ? 999 : v}.dp`);
  L.push(`}`, ``);
  L.push(`object Bands {`);
  for (const role of ROLES) {
    for (const theme of ['light', 'dark']) {
      for (const b of BANDS) {
        const n = `${b}${role === 'colour' ? '' : role[0].toUpperCase() + role.slice(1)}${theme === 'dark' ? 'Dark' : ''}`;
        L.push(`    val ${n} = Color(0xFF${bandColour(role, theme, b).slice(1).toUpperCase()})`);
      }
    }
  }
  L.push(`    val litByBand = mapOf(${Object.entries(T.rose.litByBand).map(([k, v]) => `"${k}" to ${v}`).join(', ')})`);
  L.push(`}`, ``);
  L.push(`// score -> band. CONFIRMED from the code 2026-09-21. The scorer emits`);
  L.push(`// \`fit\` ONLY and every client derives, so this must match web and iOS`);
  L.push(`// exactly. It is generated for that reason — five copies became one.`);
  L.push(`object Band {`);
  for (const [k, v] of real(T.band.threshold)) L.push(`    const val ${k.toUpperCase()} = ${v}`);
  L.push(`    fun of(fit: Int): String = when {`);
  L.push(`        fit >= AUTO -> "auto"`);
  L.push(`        fit >= PING -> "ping"`);
  L.push(`        fit >= UNSURE -> "unsure"`);
  L.push(`        else -> "nearmiss"`);
  L.push(`    }`);
  L.push(`}`, ``);
  L.push(`// Compose cannot consume linear(). Do NOT eyeball an equivalent and do NOT`);
  L.push(`// substitute Compose's named stiffness constants — the durations stop`);
  L.push(`// matching and the clients drift. Derived from the same parameters:`);
  L.push(`// w = 2*PI / durationSeconds ; stiffness = w^2`);
  L.push(`object Motion {`);
  for (const [k, s] of real(T.motion.springs)) {
    if (s.bezier) {
      L.push(`    val ${k} = tween<Float>(${s.durationMs}, easing = CubicBezierEasing(${s.bezier.map(v => v + 'f').join(', ')}))`);
    } else {
      const w = (2 * Math.PI) / (s.durationMs / 1000);
      L.push(`    val ${k} = spring<Float>(dampingRatio = ${s.zeta}f, stiffness = ${Math.round(w * w)}f)   // ${s.durationMs}ms`);
    }
  }
  L.push(`}`, ``);
  L.push(`object Rose {`);
  L.push(`    const val RING = ${T.rose.ring}f; const val BOX = ${T.rose.box}f`);
  L.push(`    const val R0 = ${T.rose.r0}f;  const val DR = ${T.rose.dr}f;  const val COUNT = ${T.rose.count}`);
  L.push(`    const val EMPTY_ALPHA = ${T.rose.emptyAlpha}f; const val EMPTY_SCALE = ${T.rose.emptyScale}f`);
  L.push(`}`);
  return L.join('\n') + '\n';
}

/* ========================================================================= */
/* Swift / SwiftUI.  response IS the natural period, so it equals duration.   */
/* ========================================================================= */
function swift() {
  const ts = typeScale(), r = radii(), L = [];
  L.push(`// GENERATED by tokens/generate.mjs — do not edit. v${T.version}`);
  L.push(`import SwiftUI`, ``);
  L.push(`enum JSType {`);
  ts.forEach((v, i) => L.push(`    static let t${i}: CGFloat = ${v}   // ${T.type.roles['t' + i]}`));
  L.push(`}`, ``);
  L.push(`enum JSSpace {`);
  T.space.steps.forEach((v, i) => L.push(`    static let s${i}: CGFloat = ${v}`));
  L.push(`}`, ``);
  L.push(`enum JSRadius {`);
  for (const [k, v] of real(r)) L.push(`    static let ${k}: CGFloat = ${k === 'pill' ? 999 : v}`);
  L.push(`}`, ``);
  L.push(`extension Color {`);
  L.push(`    init(hex: UInt32) {`);
  L.push(`        self.init(.sRGB, red: Double((hex >> 16) & 0xFF)/255,`);
  L.push(`                  green: Double((hex >> 8) & 0xFF)/255,`);
  L.push(`                  blue: Double(hex & 0xFF)/255, opacity: 1)`);
  L.push(`    }`);
  L.push(`}`, ``);
  L.push(`enum JSBands {`);
  for (const role of ROLES) {
    for (const theme of ['light', 'dark']) {
      for (const b of BANDS) {
        const n = `${b}${role === 'colour' ? '' : role[0].toUpperCase() + role.slice(1)}${theme === 'dark' ? 'Dark' : ''}`;
        L.push(`    static let ${n} = Color(hex: 0x${bandColour(role, theme, b).slice(1).toUpperCase()})`);
      }
    }
  }
  L.push(`    static let litByBand: [String: Int] = [${Object.entries(T.rose.litByBand).map(([k, v]) => `"${k}": ${v}`).join(', ')}]`);
  L.push(`}`, ``);
  L.push(`// score -> band. CONFIRMED from the code 2026-09-21. The scorer emits`);
  L.push(`// \`fit\` ONLY and every client derives, so this must match web and`);
  L.push(`// Android exactly. It is generated for that reason.`);
  L.push(`enum JSBand {`);
  for (const [k, v] of real(T.band.threshold)) L.push(`    static let ${k} = ${v}`);
  L.push(`    static func of(_ fit: Int) -> String {`);
  L.push(`        if fit >= auto { return "auto" }`);
  L.push(`        if fit >= ping { return "ping" }`);
  L.push(`        if fit >= unsure { return "unsure" }`);
  L.push(`        return "nearmiss"`);
  L.push(`    }`);
  L.push(`}`, ``);
  L.push(`// SwiftUI's \`response\` IS the natural period, so it equals the CSS duration.`);
  L.push(`enum JSMotion {`);
  for (const [k, s] of real(T.motion.springs)) {
    if (s.bezier) L.push(`    static let ${k} = Animation.easeIn(duration: ${(s.durationMs / 1000).toFixed(3)})`);
    else L.push(`    static let ${k} = Animation.spring(response: ${(s.durationMs / 1000).toFixed(3)}, dampingFraction: ${s.zeta})`);
  }
  L.push(`}`, ``);
  L.push(`enum JSRose {`);
  L.push(`    static let ring: CGFloat = ${T.rose.ring};  static let box: CGFloat = ${T.rose.box}`);
  L.push(`    static let r0: CGFloat = ${T.rose.r0};  static let dr: CGFloat = ${T.rose.dr};  static let count = ${T.rose.count}`);
  L.push(`    static let emptyAlpha = ${T.rose.emptyAlpha};  static let emptyScale: CGFloat = ${T.rose.emptyScale}`);
  L.push(`}`);
  return L.join('\n') + '\n';
}

const OUT = [
  [join(HERE, 'tokens.css'), css()],
  [join(HERE, '..', 'native', 'Tokens.kt'), kotlin()],
  [join(HERE, '..', 'native', 'Tokens.swift'), swift()],
];

let stale = 0;
for (const [path, body] of OUT) {
  let cur = null;
  try { cur = readFileSync(path, 'utf8'); } catch {}
  if (CHECK) {
    if (cur !== body) { console.error(`  ✗ stale: ${path}`); stale++; }
  } else {
    writeFileSync(path, body);
    console.log(`  wrote ${path}  (${body.split('\n').length} lines)`);
  }
}
if (CHECK) {
  if (stale) { console.error(`\n${stale} generated file(s) do not match tokens.json — run: node tokens/generate.mjs`); process.exit(1); }
  console.log('  ✓ all generated files match tokens.json');
}
